def simulate_snake(board_size, snake, food, moves):
    width, height = board_size

    if width <= 0 or height <= 0:
        raise ValueError("board_size must contain positive dimensions")

    def in_bounds(pos):
        x, y = pos
        return 0 <= x < width and 0 <= y < height

    directions = {
        "UP": (0, -1),
        "DOWN": (0, 1),
        "LEFT": (-1, 0),
        "RIGHT": (1, 0),
    }

    opposites = {
        "UP": "DOWN",
        "DOWN": "UP",
        "LEFT": "RIGHT",
        "RIGHT": "LEFT",
    }

    snake = list(snake)
    food = list(food)

    if not snake:
        raise ValueError("snake must not be empty")

    if any(not in_bounds(part) for part in snake):
        raise ValueError("all snake coordinates must be inside the board")

    if len(set(snake)) != len(snake):
        raise ValueError("snake segments must occupy distinct cells")

    if any(not in_bounds(item) for item in food):
        raise ValueError("all food coordinates must be inside the board")

    # Infer the current direction from the head and the next body segment.
    # A one-segment snake has no current direction yet.
    current_direction = None
    if len(snake) >= 2:
        hx, hy = snake[0]
        nx, ny = snake[1]
        delta = (hx - nx, hy - ny)

        for name, direction_delta in directions.items():
            if delta == direction_delta:
                current_direction = name
                break
        else:
            raise ValueError("snake body segments must be adjacent")

    food_index = 0
    food_eaten = 0
    alive = True

    for move in moves:
        if move not in directions:
            raise ValueError(f"invalid move: {move}")

        # A move directly opposite the current direction is ignored.
        if (
            current_direction is not None
            and move == opposites[current_direction]
        ):
            effective_direction = current_direction
        else:
            effective_direction = move

        current_direction = effective_direction
        dx, dy = directions[effective_direction]

        head_x, head_y = snake[0]
        new_head = (head_x + dx, head_y + dy)

        if not in_bounds(new_head):
            alive = False
            break

        will_grow = (
            food_index < len(food)
            and new_head == food[food_index]
        )

        # The tail may be entered on a normal move because it will move away.
        occupied_cells = snake if will_grow else snake[:-1]

        if new_head in occupied_cells:
            alive = False
            break

        if will_grow:
            snake = [new_head] + snake
            food_index += 1
            food_eaten += 1
        else:
            snake = [new_head] + snake[:-1]

    return snake, alive, food_eaten
